---
import { Picture } from 'astro:assets';
import QuizSidebarImage from '@/content/blog/using-genai-to-code-not-so-fast/images/ai-promise-vs-reality.jpg';

export interface Props {
  heading?: string;
  body?: string;
  imageAlt?: string;
  linkUrl?: string;
  linkText?: string;
}

const {
  heading = 'Do you know how GenAI fails?',
  body = 'Twelve questions. Three minutes. Real studies, real citations. See how GenAI is actually failing in software teams right now, and where you land against the research.',
  imageAlt = 'AI Failure Modes Quiz',
  linkUrl = '/quiz/ai-failure-modes/',
  linkText = 'Take the Quiz',
} = Astro.props;
---

<section>
  <div class="flex flex-col gap-8">
    <Picture
      src={QuizSidebarImage}
      alt={imageAlt}
      class="size-full max-h-90 object-contain"
      loading="lazy"
      widths={[400, 800]}
      sizes="(max-width: 800px) 100vw, 800px"
      formats={['avif', 'webp']}
    />

    <div class="flex flex-col gap-4">
      <div class="flex flex-col gap-2">
        <h2 class="text-2xl/7 font-bold">
          {heading}
        </h2>
        <p class="text-sm">
          {body}
        </p>
      </div>

      <a
        href={linkUrl}
        class="inline-flex h-10 items-center justify-center rounded-md bg-blue-600 px-6 py-2 text-center text-base font-semibold text-white transition-colors hover:bg-blue-700 focus:ring-2 focus:ring-blue-600 focus:ring-offset-2 focus:outline-none"
      >
        {linkText}
      </a>
    </div>
  </div>
</section>

